async () => {
  const hosts = ['google.com', 'cloudflare.com', 'github.com'];
  const dnsHosts = ['example.com', 'wikipedia.org', 'stackoverflow.com'];
  const results = { connectivity: [], dns: [], timestamp: new Date().toISOString() };

  // Connectivity tests via fetch (HTTPS HEAD-like)
  for (const host of hosts) {
    const start = performance.now();
    try {
      const res = await fetch(`https://${host}`, { method: 'GET', mode: 'no-cors', cache: 'no-store' });
      const elapsed = (performance.now() - start).toFixed(2);
      results.connectivity.push({ host, reachable: true, time_ms: elapsed, status: res.status || 'opaque' });
    } catch (e) {
      const elapsed = (performance.now() - start).toFixed(2);
      results.connectivity.push({ host, reachable: false, time_ms: elapsed, error: e.message });
    }
  }

  // DNS lookups via Cloudflare DoH
  for (const host of dnsHosts) {
    const entry = { host, A: [], AAAA: [] };
    try {
      const aRes = await fetch(`https://cloudflare-dns.com/dns-query?name=${host}&type=A`, {
        headers: { 'Accept': 'application/dns-json' }
      });
      const aJson = await aRes.json();
      entry.A = (aJson.Answer || []).filter(r => r.type === 1).map(r => r.data);
    } catch (e) { entry.A_error = e.message; }
    try {
      const aaaaRes = await fetch(`https://cloudflare-dns.com/dns-query?name=${host}&type=AAAA`, {
        headers: { 'Accept': 'application/dns-json' }
      });
      const aaaaJson = await aaaaRes.json();
      entry.AAAA = (aaaaJson.Answer || []).filter(r => r.type === 28).map(r => r.data);
    } catch (e) { entry.AAAA_error = e.message; }
    results.dns.push(entry);
  }

  // Also do DNS lookups for connectivity hosts (to enrich the report)
  results.connectivity_dns = [];
  for (const host of hosts) {
    const entry = { host, A: [] };
    try {
      const aRes = await fetch(`https://cloudflare-dns.com/dns-query?name=${host}&type=A`, {
        headers: { 'Accept': 'application/dns-json' }
      });
      const aJson = await aRes.json();
      entry.A = (aJson.Answer || []).filter(r => r.type === 1).map(r => r.data);
    } catch (e) { entry.error = e.message; }
    results.connectivity_dns.push(entry);
  }

  return results;
}
